AssistantMessageToolRequest(name='create', tool_call_id='tooluse_4w5DKiLPysvm8EhOsjoWqz', arguments={'file_text': "/* ── Reset & Base ────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black:   #0d0d0d;
  --white:   #ffffff;
  --gray-50: #f9f9f9;
  --gray-100:#f0f0f0;
  --gray-200:#e0e0e0;
  --gray-400:#9e9e9e;
  --gray-600:#555555;
  --accent:  #e84040;
  --accent-dark: #c42f2f;
  --radius:  6px;
  --transition: 0.22s ease;
  --shadow-sm: 0 1px 4px rgba(0,0,0,.08);
  --shadow-md: 0 4px 20px rgba(0,0,0,.12);
  --shadow-lg: 0 8px 40px rgba(0,0,0,.18);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
  --max-w: 1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  color: var(--black);
  background: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

/* ── Utility ─────────────────────────────────────────── */
.container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }

.badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 20px;
  background: var(--accent);
  color: var(--white);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 32px;
}

.section-header h2 {
  font-size: clamp(1.4rem, 2.5vw, 1.9rem);
  font-weight: 700;
  letter-spacing: -.02em;
}

.see-all {
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
  white-space: nowrap;
  transition: opacity var(--transition);
}
.see-all:hover { opacity: .75; }

/* ── Nav ─────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 40px;
  height: 62px;
}

.nav-logo {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -.03em;
  flex-shrink: 0;
}

.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex;
  gap: 28px;
  flex: 1;
}

.nav-links a {
  font-size: .88rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--black); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: auto;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--gray-100);
  border-radius: 24px;
  padding: 7px 14px;
  border: 1.5px solid transparent;
  transition: border-color var(--transition), background var(--transition);
}
.nav-search:focus-within {
  background: var(--white);
  border-color: var(--gray-200);
}

.nav-search input {
  border: none;
  background: transparent;
  outline: none;
  font-size: .85rem;
  width: 160px;
  font-family: inherit;
}

.nav-icon-btn {
  position: relative;
  background: none;
  border: none;
  padding: 6px;
  color: var(--black);
  transition: opacity var(--transition);
}
.nav-icon-btn:hover { opacity: .65; }

.cart-count {
  position: absolute;
  top: 0; right: 0;
  background: var(--accent);
  color: var(--white);
  font-size: 10px;
  font-weight: 700;
  width: 16px; height: 16px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
}

.nav-mobile-toggle {
  display: none;
  background: none;
  border: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}
.nav-mobile-toggle span {
  display: block;
  width: 22px; height: 2px;
  background: var(--black);
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}

/* ── Hero ────────────────────────────────────────────── */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--black);
  color: var(--white);
  min-height: 540px;
  display: flex;
  align-items: center;
}

.hero-slides { position: relative; width: 100%; }

.hero-slide {
  display: none;
  align-items: center;
  min-height: 540px;
  padding: 80px 0;
}
.hero-slide.active { display: flex; }

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: .45;
  transition: opacity 0.6s;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 560px;
}

.hero-eyebrow {
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 14px;
}

.hero-title {
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 800;
  letter-spacing: -.035em;
  line-height: 1.1;
  margin-bottom: 20px;
}

.hero-subtitle {
  font-size: 1.05rem;
  color: rgba(255,255,255,.72);
  margin-bottom: 32px;
  max-width: 400px;
}

.hero-ctas { display: flex; gap: 12px; flex-wrap: wrap; }

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  color: var(--black);
  font-size: .9rem;
  font-weight: 700;
  padding: 12px 24px;
  border-radius: var(--radius);
  border: none;
  transition: background var(--transition), transform var(--transition);
}
.btn-primary:hover { background: var(--gray-100); transform: translateY(-1px); }

.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  color: var(--white);
  font-size: .9rem;
  font-weight: 600;
  padding: 12px 24px;
  border-radius: var(--radius);
  border: 1.5px solid rgba(255,255,255,.4);
  transition: border-color var(--transition), transform var(--transition);
}
.btn-outline:hover { border-color: var(--white); transform: translateY(-1px); }

.hero-dots {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  z-index: 5;
}

.hero-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,.35);
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
}
.hero-dot.active {
  background: var(--white);
  transform: scale(1.3);
}

/* ── Promo Bar ───────────────────────────────────────── */
.promo-bar {
  background: var(--black);
  color: var(--white);
  text-align: center;
  font-size: .8rem;
  font-weight: 500;
  letter-spacing: .04em;
  padding: 10px 24px;
  border-bottom: 1px solid #1a1a1a;
}
.promo-bar strong { color: var(--accent); }

/* ── Categories ──────────────────────────────────────── */
.categories { padding: 64px 0 48px; }

.categories-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 12px;
  border-radius: 12px;
  background: var(--gray-50);
  border: 1.5px solid var(--gray-100);
  cursor: pointer;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
}
.category-card:hover {
  border-color: var(--gray-200);
  box-shadow: var(--shadow-sm);
  transform: translateY(-2px);
}

.category-icon {
  width: 52px; height: 52px;
  border-radius: 50%;
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  box-shadow: var(--shadow-sm);
}

.category-name {
  font-size: .78rem;
  font-weight: 600;
  text-align: center;
  color: var(--gray-600);
}

/* ── Products Grid ───────────────────────────────────── */
.featured-products { padding: 48px 0; }

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  border-radius: 12px;
  overflow: hidden;
  background: var(--white);
  border: 1.5px solid var(--gray-100);
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--gray-50);
}

.product-image-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-image-wrap img { transform: scale(1.05); }

.product-badges {
  position: absolute;
  top: 10px; left: 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.product-wishlist {
  position: absolute;
  top: 10px; right: 10px;
  background: var(--white);
  border: none;
  width: 32px; height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: background var(--transition), transform var(--transition);
  opacity: 0;
}
.product-card:hover .product-wishlist { opacity: 1; }
.product-wishlist:hover { background: var(--gray-100); transform: scale(1.1); }
.product-wishlist.active svg { fill: var(--accent); stroke: var(--accent); }

.product-quick-add {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  background: rgba(13,13,13,.85);
  color: var(--white);
  border: none;
  font-size: .82rem;
  font-weight: 600;
  padding: 10px;
  letter-spacing: .03em;
  transform: translateY(100%);
  transition: transform var(--transition);
}
.product-card:hover .product-quick-add { transform: translateY(0); }

.product-info { padding: 14px 16px 18px; }

.product-brand {
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 4px;
}

.product-name {
  font-size: .95rem;
  font-weight: 600;
  margin-bottom: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.product-price {
  font-size: 1rem;
  font-weight: 700;
}

.product-price .original {
  font-size: .82rem;
  font-weight: 400;
  color: var(--gray-400);
  text-decoration: line-through;
  margin-left: 5px;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: .78rem;
  color: var(--gray-600);
}

.stars { color: #f5a623; letter-spacing: -1px; }

/* ── Deals ───────────────────────────────────────────── */
.deals { padding: 48px 0; background: var(--gray-50); }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 24px;
}

.deal-card {
  border-radius: 12px;
  overflow: hidden;
  background: var(--white);
  border: 1.5px solid var(--gray-100);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}
.deal-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }

.deal-image-wrap {
  position: relative;
  aspect-ratio: 3/2;
  overflow: hidden;
  background: var(--gray-100);
}
.deal-image-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; }
.deal-card:hover .deal-image-wrap img { transform: scale(1.06); }

.deal-badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--accent);
  color: var(--white);
  font-size: .75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

.deal-body { padding: 18px 18px 20px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.deal-category { font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--accent); }
.deal-name { font-size: 1.05rem; font-weight: 700; }
.deal-desc { font-size: .84rem; color: var(--gray-600); line-height: 1.55; flex: 1; }

.deal-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
}

.deal-price { font-size: 1.1rem; font-weight: 800; }
.deal-price .original { font-size: .83rem; font-weight: 400; color: var(--gray-400); text-decoration: line-through; margin-left: 6px; }

.deal-timer {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: .75rem;
  font-weight: 600;
  color: var(--accent);
}

.timer-seg {
  background: var(--accent);
  color: var(--white);
  border-radius: 4px;
  padding: 2px 5px;
  font-size: .72rem;
  font-weight: 700;
  min-width: 26px;
  text-align: center;
}

/* ── Banner Strip ────────────────────────────────────── */
.banner-strip { padding: 48px 0; }

.banner-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.banner-card {
  border-radius: 14px;
  overflow: hidden;
  position: relative;
  min-height: 220px;
  display: flex;
  align-items: flex-end;
  cursor: pointer;
  transition: box-shadow var(--transition);
}
.banner-card:hover { box-shadow: var(--shadow-lg); }

.banner-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  transition: transform 0.5s ease;
}
.banner-card:hover .banner-bg { transform: scale(1.04); }

.banner-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.7) 0%, rgba(0,0,0,.1) 60%);
}

.banner-content {
  position: relative;
  z-index: 2;
  padding: 24px;
  color: var(--white);
}

.banner-tag {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  opacity: .8;
  margin-bottom: 6px;
}

.banner-title { font-size: 1.3rem; font-weight: 800; letter-spacing: -.02em; margin-bottom: 12px; }

.banner-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--white);
  color: var(--black);
  font-size: .8rem;
  font-weight: 700;
  padding: 8px 16px;
  border-radius: var(--radius);
  border: none;
  transition: background var(--transition);
}
.banner-btn:hover { background: var(--gray-100); }

/* ── Editorial ───────────────────────────────────────── */
.editorial { padding: 48px 0; }

.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 24px;
}

.article-card {
  border-radius: 12px;
  overflow: hidden;
  background: var(--white);
  border: 1.5px solid var(--gray-100);
  cursor: pointer;
  transition: box-shadow var(--transition), transform var(--transition);
}
.article-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.article-image {
  aspect-ratio: 16/9;
  overflow: hidden;
  background: var(--gray-100);
}
.article-image img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; }
.article-card:hover .article-image img { transform: scale(1.05); }

.article-body { padding: 18px 20px 20px; }
.article-tag { font-size: .7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--accent); margin-bottom: 8px; }

.article-card.featured .article-title { font-size: 1.25rem; }
.article-title { font-size: 1rem; font-weight: 700; letter-spacing: -.01em; margin-bottom: 8px; line-height: 1.35; }
.article-excerpt { font-size: .84rem; color: var(--gray-600); line-height: 1.6; margin-bottom: 14px; }
.article-meta { font-size: .75rem; color: var(--gray-400); }

/* ── Trust Bar ───────────────────────────────────────── */
.trust-bar { padding: 48px 0; background: var(--black); color: var(--white); }

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  text-align: center;
}

.trust-item { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.trust-icon { font-size: 2rem; }
.trust-title { font-size: .9rem; font-weight: 700; }
.trust-desc { font-size: .78rem; color: rgba(255,255,255,.55); }

/* ── Newsletter ──────────────────────────────────────── */
.newsletter { padding: 64px 0; border-top: 1px solid var(--gray-100); }

.newsletter-inner {
  max-width: 520px;
  margin: 0 auto;
  text-align: center;
}

.newsletter h2 { font-size: 1.7rem; font-weight: 800; letter-spacing: -.02em; margin-bottom: 10px; }
.newsletter p { color: var(--gray-600); margin-bottom: 28px; }

.newsletter-form {
  display: flex;
  gap: 10px;
}

.newsletter-form input {
  flex: 1;
  padding: 12px 16px;
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius);
  font-size: .9rem;
  font-family: inherit;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input:focus { border-color: var(--black); }

.btn-dark {
  background: var(--black);
  color: var(--white);
  font-size: .9rem;
  font-weight: 700;
  padding: 12px 22px;
  border: none;
  border-radius: var(--radius);
  white-space: nowrap;
  transition: background var(--transition);
}
.btn-dark:hover { background: #2a2a2a; }

.newsletter-note { margin-top: 12px; font-size: .75rem; color: var(--gray-400); }

/* ── Footer ──────────────────────────────────────────── */
.footer { background: var(--gray-50); border-top: 1px solid var(--gray-200); padding: 56px 0 32px; }

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand p { font-size: .85rem; color: var(--gray-600); margin-top: 12px; max-width: 240px; line-height: 1.65; }
.footer-logo { font-size: 1.15rem; font-weight: 800; letter-spacing: -.03em; }
.footer-logo span { color: var(--accent); }

.footer-social { display: flex; gap: 10px; margin-top: 18px; }
.social-btn {
  width: 34px; height: 34px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex; align-items: center; justify-content: center;
  font-size: .8rem;
  transition: background var(--transition);
}
.social-btn:hover { background: var(--gray-400); color: var(--white); }

.footer-col h4 { font-size: .85rem; font-weight: 700; margin-bottom: 16px; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a { font-size: .83rem; color: var(--gray-600); transition: color var(--transition); }
.footer-col ul a:hover { color: var(--black); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid var(--gray-200);
  font-size: .78rem;
  color: var(--gray-400);
}

.payment-icons { display: flex; gap: 8px; }
.payment-icon {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 4px;
  padding: 3px 8px;
  font-size: .68rem;
  font-weight: 700;
  color: var(--gray-600);
}

/* ── Notification Toast ──────────────────────────────── */
.toast {
  position: fixed;
  bottom: 32px;
  right: 32px;
  background: var(--black);
  color: var(--white);
  padding: 14px 20px;
  border-radius: 10px;
  font-size: .88rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  transform: translateY(20px);
  opacity: 0;
  pointer-events: none;
  transition: transform 0.3s ease, opacity 0.3s ease;
  z-index: 999;
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: 300px;
}
.toast.show { transform: translateY(0); opacity: 1; }
.toast-icon { font-size: 1.1rem; }

/* ── Responsive ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .categories-grid { grid-template-columns: repeat(4, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid .article-card.featured { grid-column: span 2; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-mobile-toggle { display: flex; }
  .nav-search input { width: 120px; }

  .hero-slide { min-height: 400px; padding: 60px 0; }
  .hero-title { font-size: 2.2rem; }

  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .banner-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-grid .article-card.featured { grid-column: auto; }
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-form { flex-direction: column; }
}

@media (max-width: 480px) {
  .categories-grid { grid-template-columns: repeat(2, 1fr); }
  .products-grid { grid-template-columns: 1fr 1fr; gap: 12px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .nav-search { display: none; }
}
