  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  box-shadow: var(--shadow-sm);
}

.category-name {
  font-size: .78rem;
  font-weight: 600;
  text-align: center;
  color: var(--gray-600);
}

/* ── Products Grid ───────────────────────────────────── */
.featured-products { padding: 48px 0; }

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
