.product-card:hover .product-wishlist { opacity: 1; }
.product-wishlist:hover { background: var(--gray-100); transform: scale(1.1); }
.product-wishlist.active svg { fill: var(--accent); stroke: var(--accent); }

.product-quick-add {
  position: absolute;
