  font-weight: 600;
  padding: 10px;
  letter-spacing: .03em;
  transform: translateY(100%);
  transition: transform var(--transition);
}
.product-card:hover .product-quick-add { transform: translateY(0); }

.product-info { padding: 14px 16px 18px; }

.product-brand {
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--gray-400);
  margin-bottom: 4px;
}

.product-name {
  font-size: .95rem;
  font-weight: 600;
  margin-bottom: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
