.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.product-price {
  font-size: 1rem;
  font-weight: 700;
}

.product-price .original {
  font-size: .82rem;
  font-weight: 400;
  color: var(--gray-400);
  text-decoration: line-through;
  margin-left: 5px;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: .78rem;
  color: var(--gray-600);
}

.stars { color: #f5a623; letter-spacing: -1px; }

/* ── Deals ───────────────────────────────────────────── */
.deals { padding: 48px 0; background: var(--gray-50); }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 24px;
}

.deal-card {
  border-radius: 12px;
  overflow: hidden;
  background: var(--white);
  border: 1.5px solid var(--gray-100);
