.deal-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }

.deal-image-wrap {
  position: relative;
  aspect-ratio: 3/2;
  overflow: hidden;
  background: var(--gray-100);
}
.deal-image-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; }
.deal-card:hover .deal-image-wrap img { transform: scale(1.06); }

.deal-badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--accent);
  color: var(--white);
  font-size: .75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

.deal-body { padding: 18px 18px 20px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.deal-category { font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--accent); }
.deal-name { font-size: 1.05rem; font-weight: 700; }
.deal-desc { font-size: .84rem; color: var(--gray-600); line-height: 1.55; flex: 1; }

.deal-footer {
  display: flex;
