/* ── Banner Strip ────────────────────────────────────── */
.banner-strip { padding: 48px 0; }

.banner-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.banner-card {
  border-radius: 14px;
