  const dots = document.querySelectorAll(".hero-dot");
  slides[currentSlide]?.classList.remove("active");
  dots[currentSlide]?.classList.remove("active");
  currentSlide = index;
  slides[currentSlide]?.classList.add("active");
  dots[currentSlide]?.classList.add("active");
}

// ── Deal Timers ───────────────────────────────────────
function initDealTimers() {
  DEALS.forEach(d => {
    dealTimers[d.id] = d.endsIn;
    updateTimerDisplay(d.id);
  });
  setInterval(() => {
    DEALS.forEach(d => {
      if (dealTimers[d.id] > 0) {
        dealTimers[d.id]--;
        updateTimerDisplay(d.id);
      }
    });
  }, 1000);
}

function updateTimerDisplay(id) {
  const el = document.getElementById(`timer-${id}`);
  if (!el) return;
  const secs = dealTimers[id];
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  el.innerHTML = `
    <span class="timer-seg">${pad(h)}</span>:
    <span class="timer-seg">${pad(m)}</span>:
    <span class="timer-seg">${pad(s)}</span>
  `;
}

function pad(n) { return String(n).padStart(2, "0"); }

// ── Cart ──────────────────────────────────────────────
function addToCart(e, id, name) {
  e.stopPropagation();
  cartCount++;
  syncCartBadge();
  showToast(`🛒 "${truncate(name, 28)}" added to cart`);
}

function syncCartBadge() {
  const badge = document.getElementById("cart-count");
  if (badge) {
    badge.textContent = cartCount;
    badge.style.display = cartCount > 0 ? "flex" : "none";
  }
}

// ── Wishlist ──────────────────────────────────────────
function toggleWishlist(e, id) {
  e.stopPropagation();
  if (wishlist.has(id)) {
    wishlist.delete(id);
    showToast("💔 Removed from wishlist");
  } else {
    wishlist.add(id);
    showToast("❤️ Saved to wishlist");
  }
  const btn = e.currentTarget;
  btn.classList.toggle("active", wishlist.has(id));
}

// ── Click Handlers ────────────────────────────────────
function handleProductClick(id) { showToast("🔍 Opening product…"); }
function handleDealClick(id) { showToast("⚡ Grabbing deal…"); }
function handleArticleClick(id) { showToast("📖 Opening article…"); }

// ── Newsletter ────────────────────────────────────────
function initNewsletterForm() {
  const form = document.getElementById("newsletter-form");
  if (!form) return;
  form.addEventListener("submit", e => {
    e.preventDefault();
    const input = form.querySelector("input[type=email]");
    if (!input.value.includes("@")) {
      showToast("⚠️ Please enter a valid email");
      return;
    }
    showToast("🎉 You're subscribed! Check your inbox.");
    input.value = "";
  });
}

// ── Mobile Nav ────────────────────────────────────────
function initMobileNav() {
  const toggle = document.getElementById("mobile-toggle");
  const links = document.getElementById("nav-links");
  if (!toggle || !links) return;
  toggle.addEventListener("click", () => {
    const open = links.style.display === "flex";
    links.style.display = open ? "" : "flex";
    links.style.flexDirection = "column";
    links.style.position = "absolute";
    links.style.top = "62px";
    links.style.left = "0";
    links.style.right = "0";
    links.style.background = "var(--white)";
    links.style.padding = "16px 24px";
    links.style.borderBottom = "1px solid var(--gray-200)";
    links.style.zIndex = "99";
    links.style.gap = "16px";
  });
}

// ── Toast ─────────────────────────────────────────────
let toastTimer;
function showToast(msg) {
  const t = document.getElementById("toast");
  if (!t) return;
  t.querySelector(".toast-msg").textContent = msg;
  t.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("show"), 2800);
}

// ── Helpers ───────────────────────────────────────────
function starHTML(rating) {
  const full = Math.floor(rating);
  const half = rating % 1 >= 0.5;
  return "★".repeat(full) + (half ? "½" : "") + "☆".repeat(5 - full - (half ? 1 : 0));
}

function truncate(str, n) { return str.length > n ? str.slice(0, n) + "…" : str; }
function escHtml(s) { return s.replace(/'/g, "\\'"); }
