    badge.style.display = cartCount > 0 ? "flex" : "none";
  }
}

// ── Wishlist ──────────────────────────────────────────
function toggleWishlist(e, id) {
  e.stopPropagation();
  if (wishlist.has(id)) {
    wishlist.delete(id);
    showToast("💔 Removed from wishlist");
  } else {
    wishlist.add(id);
    showToast("❤️ Saved to wishlist");
  }
  const btn = e.currentTarget;
  btn.classList.toggle("active", wishlist.has(id));
}

